function motoUseFields(){return[{name:'pessoa',label:'Quem pegou a moto?',required:true},{name:'saida',label:'Data e horário da saída',required:true},{name:'devolucao',label:'Data e horário da devolução (opcional)'},{type:'section',label:'QUILOMETRAGEM — OPCIONAL'},{name:'odometroInicio',label:'Hodômetro na saída (km) — deixe vazio se não souber'},{name:'odometroFim',label:'Hodômetro na devolução (km) — deixe vazio se não souber'},{name:'observacao',label:'Observações'}]}
function addMotoUse(id){let old=id?(S.motoUses||[]).find(x=>x.id===id):null;if(id&&!old)return;openForm(old?'Editar empréstimo':'Registrar empréstimo da moto',motoUseFields(),old?{...old}:{saida:new Date().toISOString().slice(0,16).replace('T',' ')},v=>{let start=String(v.odometroInicio??'').trim()===''?null:Number(v.odometroInicio),end=String(v.odometroFim??'').trim()===''?null:Number(v.odometroFim);if((start!==null&&(!Number.isFinite(start)||start<0))||(end!==null&&(!Number.isFinite(end)||end<0))){alert('Informe uma quilometragem válida ou deixe o campo vazio.');return false}if(start!==null&&end!==null&&end<start){alert('O hodômetro da devolução não pode ser menor que o da saída.');return false}let record={id:old?.id||'moto-use-'+Date.now(),pessoa:String(v.pessoa||'').trim(),saida:v.saida||'',devolucao:v.devolucao||'',odometroInicio:start,odometroFim:end,observacao:v.observacao||''};if(old)Object.assign(old,record);else{S.motoUses=S.motoUses||[];S.motoUses.push(record)}if(end!==null)motoProfile().odometroAtual=Math.max(+motoProfile().odometroAtual||0,end);save();render()})}
function fuelFields(){return[{name:'data',label:'Data do abastecimento',type:'date',required:true},{name:'valor',label:'Valor abastecido (R$)',type:'number',min:0.01,step:'.01',required:true},{name:'pagador',label:'Quem pagou?',type:'select',options:[{value:'proprio',label:'Eu paguei'},{value:'terceiro',label:'Outra pessoa pagou'}]},{name:'responsavel',label:'Nome de quem abasteceu/pagou (opcional)'},{name:'usoId',label:'Relacionar a um empréstimo (opcional)',type:'select',options:[{value:'',label:'Não relacionar'},...(S.motoUses||[]).map(u=>({value:u.id,label:u.pessoa+' · '+u.saida}))]},{name:'tipo',label:'Forma de pagamento (se você pagou)',type:'select',options:['Débito','Crédito','Pix','Dinheiro']},{name:'bancoId',label:'Conta utilizada (se você pagou)',type:'select',options:[{value:'',label:'Não informar'},...S.banks.map(b=>({value:b.id,label:b.nome}))]},{type:'section',label:'DETALHES OPCIONAIS DO ABASTECIMENTO'},{name:'litros',label:'Quantidade abastecida (litros) — opcional',type:'number',min:0,step:'.001'},{name:'precoLitro',label:'Preço por litro (R$) — opcional',type:'number',min:0,step:'.001'},{name:'odometro',label:'Quilometragem atual no painel (km) — opcional',type:'number',min:0,step:'.1'},{name:'tanqueCheio',label:'Completei o tanque nesta parada?',type:'checkbox'},{name:'observacao',label:'Observações'}]}

