function addFuelTrip(id){let x=S.fuelRecords.find(r=>r.id===id);if(!x)return;openForm('Adicionar viagem',fuelTripFields(),{data:new Date().toISOString().slice(0,10),km:''},v=>{let km=+v.km||0;if(km<=0){alert('Informe a distância percorrida em quilômetros.');return false}x.viagens=x.viagens||[];x.viagens.push({id:'trip-'+Date.now(),...v,km,problema:v.problema==='1'});save();setTimeout(()=>openFuelRecord(id),0)})}
function editFuelTrip(id,tripId){let x=S.fuelRecords.find(r=>r.id===id),t=x?.viagens?.find(z=>z.id===tripId);if(!x||!t)return;openForm('Editar viagem',fuelTripFields(),{...t,km:+t.km||0,problema:t.problema?'1':'0'},v=>{let km=+v.km||0;if(km<=0){alert('Informe a distância percorrida em quilômetros.');return false}Object.assign(t,v,{km,problema:v.problema==='1'});save();setTimeout(()=>openFuelRecord(id),0)})}function editFuelRecord(id){let x=S.fuelRecords.find(r=>r.id===id);if(!x)return;openForm('Editar abastecimento',fuelFields(),{...x,tanqueCheio:x.tanqueCheio?'1':'0'},v=>{if(!v.data)return false;Object.assign(x,v,{valor:+v.valor||0,pagador:v.pagador||'proprio',responsavel:v.responsavel||'',usoId:v.usoId||'',litros:+v.litros||0,precoLitro:+v.precoLitro||(v.litros?(+v.valor||0)/(+v.litros||1):0),odometro:+v.odometro||0,tanqueCheio:v.tanqueCheio==='1',detalhesPendentes:!(+v.litros||0)});syncFuelExpense(x);if(x.odometro>0)motoProfile().odometroAtual=Math.max(+motoProfile().odometroAtual||0,x.odometro);save();render()})}function addMotoExpense(){let k=S.keys.includes(today)?today.slice(0,7):S.keys[S.keys.length-1];if(!k)k=S.keys[S.keys.length-1];if(!k)return;openForm('Registrar despesa da moto',[{name:'nome',label:'Descrição',required:true},{name:'data',label:'Data',type:'date',required:true},{name:'cat',label:'Categoria',type:'select',options:['Moto · Gasolina','Moto · Manutenção','Moto · Peças','Moto · Documentos','Moto · Outros'].map(x=>({value:x,label:x.replace('Moto · ','')}))},{name:'valor',label:'Valor (R$)',type:'number',min:.01,step:'.01',required:true},{name:'tipo',label:'Forma de pagamento',type:'select',options:['Débito','Crédito','Pix','Dinheiro']},{name:'bancoId',label:'Conta utilizada',type:'select',options:[{value:'',label:'Não informar'},...S.banks.map(b=>({value:b.id,label:b.nome}))]},{name:'observacao',label:'Observações'}],{data:new Date().toISOString().slice(0,10),cat:'Moto · Gasolina',valor:0,tipo:'Débito'},v=>{let month=v.data.slice(0,7);M(month).gastos.push({id:'moto-'+Date.now(),nome:v.nome,dia:+v.data.slice(8,10),tipo:v.tipo,cat:v.cat,bancoId:v.bancoId||'',valor:+v.valor||0,observacao:v.observacao||'',pago:true});if(!S.keys.includes(month)){S.keys.push(month);S.keys.sort()}save()})}
function entriesView(){let month=window.__entriesMonth||'todos',all=(S.movements||[]).slice(),rows=all.filter(x=>month==='todos'||String(x.data||'').slice(0,7)===month).sort((a,b)=>String(b.data).localeCompare(String(a.data))),total=rows.filter(x=>x.tipo!=='Reembolso de despesa compartilhada').reduce((n,x)=>n+(+x.valor||0),0),reimbursements=rows.filter(x=>x.tipo==='Reembolso de despesa compartilhada').reduce((n,x)=>n+(+x.valor||0),0),months=[...new Set(all.map(x=>String(x.data||'').slice(0,7)).filter(x=>/^\d{4}-\d{2}$/.test(x)))].sort().reverse();return head('ENTRADAS','Registre o dinheiro que chega.','Acompanhe cada entrada por data, origem e instituição.',button('＋','new-entry','icon-button'))+'<div class="metrics">'+metric('Entradas no período',brl(total),'Sem reembolsos de despesas compartilhadas')+metric('Reembolsos recebidos',brl(reimbursements),'Valores recuperados de despesas compartilhadas')+metric('Lançamentos',rows.length,'Movimentações registradas')+'</div><section class="panel"><div class="panel-head"><div><h2>Histórico de entradas</h2><p>Filtre por mês para consultar os recebimentos daquele período.</p></div><label class="entries-month-filter">Mês <select data-change="entries-month"><option value="todos" '+(month==='todos'?'selected':'')+'>Todos os meses</option>'+months.map(x=>'<option value="'+x+'" '+(month===x?'selected':'')+'>'+esc(full(x))+'</option>').join('')+'</select></label></div>'+(rows.length?'<div class="entry-compact-list">'+rows.map(x=>'<div class="entry-compact-row"><div class="entry-compact-info"><b>'+esc(x.nome)+'</b><small>'+esc(x.data||'')+' · '+esc(S.banks.find(b=>b.id===x.bancoId)?.nome||'Conta não informada')+'</small><small class="entry-compact-kind">'+esc(x.tipo||'Entrada')+(x.includeInBalance===false?' · Reservada':'')+'</small></div><strong>'+brl(x.valor)+'</strong><button class="icon-action" data-action="edit-entry" data-id="'+esc(x.id)+'" aria-label="Editar entrada">✎</button><button class="icon-action danger" data-action="delete-entry" data-id="'+esc(x.id)+'" aria-label="Excluir entrada">×</button></div>').join('')+'</div>':'<p class="empty">Não há entradas neste período. Use o botão de adicionar para começar.</p>')+'</section>'}
function sharedExpensesView(k){let m=M(k),list=m.despesasCompartilhadas||[];return '<section class="panel shared-expenses-panel"><div class="panel-head"><div><p class="eyebrow">RATEIOS E REEMBOLSOS</p><h2>Despesas compartilhadas</h2><p>Acompanhe o que você pagou, o que já recebeu e o que ainda falta receber.</p></div>'+button('＋ Nova despesa','new-shared-expense','primary','data-month="'+k+'"')+'</div>'+(list.length?'<div class="shared-expense-list">'+list.map(x=>{let rec=x.participantes.reduce((n,p)=>n+(+p.pago||0),0),due=x.participantes.reduce((n,p)=>n+(+p.valor||0),0),pending=Math.max(0,due-rec);return '<article class="shared-expense-card"><button class="shared-expense-main" data-action="shared-detail" data-id="'+esc(x.id)+'"><span class="shared-expense-copy"><b>'+esc(x.nome)+'</b><small>'+esc(x.data)+' · '+x.participantes.length+' '+(x.participantes.length===1?'participante':'participantes')+' · Sua parte '+brl(x.minhaParte)+'</small></span><span class="shared-expense-amount"><b>'+brl(x.valor)+'</b><small>'+ (pending>0?'A receber '+brl(pending):'Rateio recebido')+'</small></span><span class="shared-expense-chevron">›</span></button><div class="shared-expense-actions"><button type="button" class="button text" data-action="shared-detail" data-id="'+esc(x.id)+'">Gerenciar pessoas</button><button type="button" class="button text" data-action="edit-shared-expense" data-id="'+esc(x.id)+'">Editar despesa</button><button type="button" class="button text danger" data-action="delete-shared-expense" data-id="'+esc(x.id)+'">Excluir</button></div></article>'}).join('')+'</div>':'<div class="shared-expenses-empty"><span class="shared-empty-icon">↗</span><b>Nenhum rateio neste mês</b><p>Adicione uma despesa paga por você que será dividida com outras pessoas.</p></div>')+'</section>'}
function newSharedExpense(k){
 const d=document.createElement('dialog');d.className='finance-dialog shared-expense-dialog';
 const bankOptions='<option value="">Selecione o banco</option>'+S.banks.map(b=>'<option value="'+esc(b.id)+'">'+esc(b.nome)+'</option>').join('');
 d.innerHTML='<form class="shared-expense-form"><div class="dialog-head"><div><p class="eyebrow">RATEIO DE DESPESA</p><h2>Adicionar despesa compartilhada</h2><p>Cadastre cada pessoa separadamente. O recebimento será lançado individualmente.</p></div><button type="button" class="button secondary" data-close>×</button></div><div class="dialog-fields"><label>Descrição da despesa<input name="nome" required placeholder="Ex.: compra do mercado, conta de luz"></label><label>Data em que você pagou<input name="data" type="date" value="'+k+'-01" required></label><label>Sua parte (R$)<input name="minhaParte" type="number" min="0" step=".01" value="0" required></label><label>Banco/conta de onde saiu o pagamento<select name="bancoId">'+bankOptions+'</select></label></div><div class="shared-person-editor-head"><div><b>Pessoas incluídas no rateio</b><small>Adicione uma linha para cada pessoa.</small></div><button type="button" class="button secondary" data-add-person>＋ Adicionar pessoa</button></div><div class="shared-person-editor-list"></div><div class="shared-expense-total"><span>Total da despesa</span><strong data-shared-total>R$ 0,00</strong></div><div class="dialog-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button type="submit" class="button primary">Salvar despesa</button></div></form>';
 const list=d.querySelector('.shared-person-editor-list');
 const updateTotal=()=>{let mine=+d.querySelector('[name="minhaParte"]').value||0,others=[...list.querySelectorAll('[data-person-value]')].reduce((n,x)=>n+(+x.value||0),0);d.querySelector('[data-shared-total]').textContent=brl(mine+others)};
 const addPerson=(person={})=>{const row=document.createElement('section');row.className='shared-person-editor-row';row.innerHTML='<div class="shared-person-editor-title"><b>Participante</b><button type="button" class="icon-action danger" aria-label="Remover pessoa">×</button></div><div class="shared-person-editor-fields"><label>Nome da pessoa<input data-person-name required placeholder="Nome"></label><label>Valor devido (R$)<input data-person-value type="number" min=".01" step=".01" value="'+(person.valor||'')+'" required></label><label>Quantidade de pessoas<input data-person-count type="number" min="1" step="1" value="'+(person.pessoas||1)+'" required></label><label>Data em que pagou<input data-person-date type="date" value="'+(person.dataRecebimento||new Date().toISOString().slice(0,10))+'"></label><label>Banco em que recebeu<select data-person-bank>'+bankOptions+'</select></label></div><label class="shared-person-paid"><input data-person-paid type="checkbox" '+(person.pago?'checked':'')+'> Já me pagou</label>';row.querySelector('[data-person-bank]').value=person.bancoRecebimentoId||'';row.querySelector('[aria-label="Remover pessoa"]').onclick=()=>{row.remove();updateTotal()};row.querySelectorAll('input').forEach(el=>el.addEventListener('input',updateTotal));row.querySelector('[data-person-paid]').addEventListener('change',()=>row.classList.toggle('is-received',row.querySelector('[data-person-paid]').checked));list.appendChild(row);row.classList.toggle('is-received',!!person.pago);updateTotal()};
 d.querySelector('[data-add-person]').onclick=()=>addPerson();d.querySelector('[name="minhaParte"]').addEventListener('input',updateTotal);d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());addPerson();
 d.querySelector('form').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.currentTarget),people=[...list.querySelectorAll('.shared-person-editor-row')].map(row=>({nome:row.querySelector('[data-person-name]').value.trim(),valor:+row.querySelector('[data-person-value]').value||0,pago:row.querySelector('[data-person-paid]').checked?(+row.querySelector('[data-person-value]').value||0):0,pessoas:Math.max(1,+row.querySelector('[data-person-count]').value||1),dataRecebimento:row.querySelector('[data-person-date]').value||'',bancoRecebimentoId:row.querySelector('[data-person-bank]').value||''}));let mine=+fd.get('minhaParte')||0,total=mine+people.reduce((n,p)=>n+p.valor,0);if(!people.length||people.some(p=>!p.nome||p.valor<=0)){appToast('Adicione pelo menos uma pessoa e confira os valores.','error');return}let month=String(fd.get('data')).slice(0,7),id='shared-'+Date.now(),expense={id,nome:String(fd.get('nome')).trim(),data:String(fd.get('data')),valor:total,minhaParte:mine,bancoId:String(fd.get('bancoId')||''),participantes:people};M(month).despesasCompartilhadas.push(expense);people.forEach((p,i)=>{if(p.pago>0)S.movements.push({id:'mv'+Date.now()+'-'+i,nome:'Reembolso de despesa compartilhada — '+expense.nome+' — '+p.nome,valor:p.pago,data:p.dataRecebimento||expense.data,bancoId:p.bancoRecebimentoId||'',tipo:'Reembolso de despesa compartilhada',includeInBalance:true,sharedExpenseId:id,sharedPersonIndex:i})});if(!S.keys.includes(month)){S.keys.push(month);S.keys.sort()}save();d.close();render()};
 document.body.appendChild(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();
}
function findSharedExpense(id){for(const k of S.keys){let x=(M(k).despesasCompartilhadas||[]).find(z=>z.id===id);if(x)return{month:k,expense:x}}return null}
function closeDialogThen(dialog,callback){if(dialog?.open){dialog.addEventListener('close',()=>{dialog.remove();if(typeof callback==='function')callback()},{once:true});dialog.close();return}if(dialog?.isConnected)dialog.remove();if(typeof callback==='function')callback()}
function editSharedExpense(id){let found=findSharedExpense(id);if(!found)return;let {month,expense:x}=found;openForm('Editar despesa compartilhada',[{name:'nome',label:'Descrição da despesa',required:true},{name:'data',label:'Data em que você pagou',type:'date',required:true},{name:'minhaParte',label:'Sua parte (R$)',type:'number',min:0,step:'.01',required:true},{name:'bancoId',label:'Conta de onde saiu o pagamento',type:'select',options:[{value:'',label:'Não informar'},...S.banks.map(b=>({value:b.id,label:b.nome}))]}],{nome:x.nome,data:x.data,minhaParte:x.minhaParte,bancoId:x.bancoId||''},v=>{let mine=Math.max(0,+v.minhaParte||0),others=x.participantes.reduce((n,p)=>n+(+p.valor||0),0);if(!v.nome.trim()||!v.data)return false;x.nome=v.nome.trim();x.data=v.data;x.minhaParte=mine;x.valor=mine+others;x.bancoId=v.bancoId||'';save();render()})}
function deleteSharedExpense(id){let found=findSharedExpense(id);if(!found)return;let x=found.expense;if(!confirm('Excluir a despesa compartilhada "'+x.nome+'" e os reembolsos vinculados a ela? Esta ação não pode ser desfeita.'))return;S.movements=S.movements.filter(m=>m.sharedExpenseId!==id);S.keys.forEach(k=>{let m=M(k);m.despesasCompartilhadas=(m.despesasCompartilhadas||[]).filter(z=>z.id!==id)});save();const dialog=document.querySelector('.shared-expense-dialog');closeDialogThen(dialog,()=>{render();appToast('Despesa compartilhada excluída.','success')})}
function sharedExpenseDetail(id){let found=findSharedExpense(id);if(!found)return;let x=found.expense,received=x.participantes.reduce((n,p)=>n+(+p.pago||0),0),due=x.participantes.reduce((n,p)=>n+(+p.valor||0),0),d=document.createElement('dialog');d.className='finance-dialog shared-expense-dialog';d.innerHTML='<div class="dialog-head"><div><p class="eyebrow">DESPESA COMPARTILHADA</p><h2>'+esc(x.nome)+'</h2><small>'+esc(x.data)+'</small></div><button class="button secondary" data-close>×</button></div><div class="fuel-detail-summary"><div><small>Total da despesa</small><b>'+brl(x.valor)+'</b></div><div><small>Sua parte</small><b>'+brl(x.minhaParte)+'</b></div><div><small>Recebido</small><b>'+brl(received)+'</b></div><div><small>A receber</small><b>'+brl(Math.max(0,due-received))+'</b></div></div><div class="shared-people-list">'+x.participantes.map((p,i)=>'<div class="shared-person-row"><button type="button" class="shared-person-edit" data-action="shared-edit-person" data-id="'+esc(x.id)+'" data-person="'+i+'" aria-label="Editar participante"><b>'+esc(p.nome)+'</b><small>Deve '+brl(p.valor)+' · Recebeu '+brl(p.pago||0)+' · '+(p.formaRecebimento==='dinheiro'?'Em espécie':p.bancoRecebimentoId?(S.banks.find(b=>b.id===p.bancoRecebimentoId)?.nome||'Conta bancária'):'Recebimento não informado')+'</small><span class="shared-person-edit-hint">✎ Editar participante</span></button>'+(S.movements.filter(m=>m.sharedExpenseId===id&&m.sharedPersonIndex===i).length?'<div class="shared-payment-history">'+S.movements.filter(m=>m.sharedExpenseId===id&&m.sharedPersonIndex===i).map(m=>'<small>'+esc(m.data||'Data não informada')+' · '+brl(m.valor)+' · '+(m.formaRecebimento==='dinheiro'?'Dinheiro':(S.banks.find(b=>b.id===m.bancoId)?.nome||'Pix / transferência'))+'</small>').join('')+'</div>':'')+'<span class="shared-status status-'+(p.pago>=p.valor?'quitado':p.pago>0?'parcial':'pendente')+'">'+(p.pago>=p.valor?'Quitado':p.pago>0?'Parcial':'Pendente')+'</span><button type="button" class="button text shared-person-edit-action" data-action="shared-edit-person" data-id="'+esc(x.id)+'" data-person="'+i+'">Editar</button><button type="button" class="button text danger" data-action="shared-remove-person" data-id="'+esc(x.id)+'" data-person="'+i+'">Excluir pessoa</button><button type="button" class="button text" data-action="shared-payment" data-id="'+esc(x.id)+'" data-person="'+i+'" '+(p.pago>=p.valor?'disabled':'')+'>＋ Pix</button></div>').join('')+'</div><p class="micro">Pix recebidos são reembolsos, não renda. Somente sua parte entra nas despesas pessoais.</p><div class="dialog-actions"><button class="button text danger" data-action="delete-shared-expense" data-id="'+esc(x.id)+'">Excluir despesa</button><button class="button secondary" data-action="edit-shared-expense" data-id="'+esc(x.id)+'">Editar</button><button class="button secondary" data-close>Fechar</button></div>';document.body.appendChild(d);d.querySelectorAll('[data-close]').forEach(btn=>btn.onclick=()=>d.close());d.querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const action=btn.dataset.action;if(action==='shared-payment'){const person=+btn.dataset.person;closeDialogThen(d,()=>registerSharedPayment(id,person))}else if(action==='shared-edit-person'){const person=Number(btn.dataset.person);openSharedPersonEditor(id,person)}else if(action==='shared-remove-person'){removeSharedPerson(id,+btn.dataset.person)}else if(action==='edit-shared-expense'){closeDialogThen(d,()=>editSharedExpense(id))}else if(action==='delete-shared-expense'){deleteSharedExpense(id)}}));d.showModal()}
function registerSharedPayment(id,index){let x=S.keys.flatMap(k=>M(k).despesasCompartilhadas||[]).find(z=>z.id===id);if(!x)return;let p=x.participantes[index],remaining=Math.max(0,(+p.valor||0)-(+p.pago||0));openForm('Registrar recebimento · '+p.nome,[{name:'valor',label:'Valor recebido (R$)',type:'number',min:.01,max:remaining,step:'.01',required:true},{name:'data',label:'Data do recebimento',type:'date',required:true},{name:'formaRecebimento',label:'Como recebeu?',type:'select',options:[{value:'dinheiro',label:'Dinheiro em espécie'},{value:'banco',label:'Transferência / Pix bancário'}]},{name:'bancoId',label:'Conta que recebeu',type:'select',options:[{value:'',label:'Selecione a conta'},...S.banks.map(b=>({value:b.id,label:b.nome}))],showIf:{field:'formaRecebimento',value:'banco'}}],{valor:remaining,data:new Date().toISOString().slice(0,10),formaRecebimento:p.formaRecebimento||'banco',bancoId:p.bancoRecebimentoId||''},v=>{let amount=+v.valor||0,form=v.formaRecebimento||'dinheiro';if(amount<=0||amount>remaining+.001)return false;if(form==='banco'&&!v.bancoId){appToast('Selecione a conta que recebeu.','error');return false}p.pago=(+p.pago||0)+amount;p.dataRecebimento=v.data;p.formaRecebimento=form;p.bancoRecebimentoId=form==='banco'?v.bancoId:'';S.movements.push({id:'mv'+Date.now(),nome:'Reembolso de despesa compartilhada — '+x.nome+' — '+p.nome,valor:amount,data:v.data,bancoId:form==='banco'?v.bancoId:'__cash__',tipo:'Reembolso de despesa compartilhada',includeInBalance:true,sharedExpenseId:id,sharedPersonIndex:index,formaRecebimento:form});save()})}
function openSharedPersonEditor(id,index){const detail=document.querySelector('.shared-expense-dialog');if(detail?.open){closeDialogThen(detail,()=>editSharedPerson(id,index));return}editSharedPerson(id,index)}
function editSharedPerson(id,index){
 const found=findSharedExpense(id);if(!found)return;const x=found.expense,p=x.participantes[index];if(!p)return;
 const oldName=p.nome,linked=S.movements.filter(m=>m.sharedExpenseId===id&&(m.sharedPersonIndex===index||(m.sharedPersonIndex==null&&String(m.nome||'').includes('— '+oldName))));
 const paid=linked.length?linked.reduce((n,m)=>n+(+m.valor||0),0):(+p.pago||0),last=linked.slice().sort((a,b)=>String(b.data||'').localeCompare(String(a.data||'')))[0];
 const method=p.formaRecebimento||(p.bancoRecebimentoId||last?.bancoId?'banco':'dinheiro'),bankId=p.bancoRecebimentoId||last?.bancoId||'';
 openForm('Editar participante · '+p.nome,[{type:'section',label:'Identificação e rateio'},{name:'nome',label:'Nome completo',required:true},{name:'valor',label:'Valor total que deve (R$)',type:'number',min:.01,step:'.01',required:true},{name:'pessoas',label:'Quantidade de pessoas representadas',type:'number',min:1,step:1,required:true},{name:'observacao',label:'Descrição / observações',type:'textarea'},{type:'section',label:'Situação dos pagamentos'},{name:'pago',label:'Total já recebido (R$)',type:'number',min:0,step:'.01',required:true},{name:'dataRecebimento',label:'Data do último recebimento',type:'date'},{name:'formaRecebimento',label:'Forma do último recebimento',type:'select',options:[{value:'dinheiro',label:'Dinheiro em espécie'},{value:'banco',label:'Pix / transferência bancária'}]},{name:'bancoRecebimentoId',label:'Conta bancária que recebeu',type:'select',options:[{value:'',label:'Selecione a conta'},...S.banks.map(b=>({value:b.id,label:b.nome}))],showIf:{field:'formaRecebimento',value:'banco'}}],{nome:p.nome,valor:p.valor,pessoas:p.pessoas||1,observacao:p.observacao||'',pago:paid,dataRecebimento:p.dataRecebimento||last?.data||'',formaRecebimento:method,bancoRecebimentoId:bankId},v=>{
 const due=+v.valor||0,received=+v.pago||0,form=v.formaRecebimento||'dinheiro';if(!v.nome.trim()||due<=0||received>due+.001){appToast('Confira os valores: o recebido não pode superar o valor devido.','error');return false}if(received>0&&!v.dataRecebimento){appToast('Informe a data do último recebimento.','error');return false}if(received>0&&form==='banco'&&!v.bancoRecebimentoId){appToast('Selecione a conta bancária que recebeu.','error');return false}
 Object.assign(p,{nome:v.nome.trim(),valor:due,pessoas:Math.max(1,+v.pessoas||1),observacao:v.observacao||'',pago:received,formaRecebimento:form,dataRecebimento:received?v.dataRecebimento:'',bancoRecebimentoId:received&&form==='banco'?v.bancoRecebimentoId:''});
 const history=[...linked].sort((a,b)=>String(a.data||'').localeCompare(String(b.data||'')));history.forEach(m=>{m.nome='Reembolso de despesa compartilhada — '+x.nome+' — '+p.nome;m.sharedPersonIndex=index});
 if(history.length){let delta=received-paid,lastMovement=history[history.length-1];if(delta>=0)lastMovement.valor=(+lastMovement.valor||0)+delta;else{let reduction=-delta;for(let i=history.length-1;i>=0&&reduction>0;i--){let movement=history[i],current=Math.max(0,+movement.valor||0),take=Math.min(current,reduction);movement.valor=current-take;reduction-=take}}if(received>0){lastMovement.data=v.dataRecebimento;lastMovement.formaRecebimento=form;lastMovement.bancoId=form==='banco'?v.bancoRecebimentoId:''}}
 else if(received>0)S.movements.push({id:'mv'+Date.now(),nome:'Reembolso de despesa compartilhada — '+x.nome+' — '+p.nome,valor:received,data:v.dataRecebimento,bancoId:form==='banco'?v.bancoRecebimentoId:'',tipo:'Reembolso de despesa compartilhada',includeInBalance:true,sharedExpenseId:id,sharedPersonIndex:index,formaRecebimento:form});
 x.valor=(+x.minhaParte||0)+x.participantes.reduce((n,z)=>n+(+z.valor||0),0);save();render();
 },()=>{if(cur!=='receivables'){const detail=document.querySelector('.shared-expense-dialog');closeDialogThen(detail,()=>sharedExpenseDetail(id))}});
}
function receivablesView(){
 const own=Array.isArray(S.receivables)?S.receivables:[];
 const shared=[];S.keys.forEach(k=>{const month=S.months[k]||{};(month.despesasCompartilhadas||[]).forEach(x=>(x.participantes||[]).forEach((p,i)=>shared.push({x,p,i,k})))});
 const isPaid=(total,paid)=>(+total||0)>.009&&Math.max(0,(+total||0)-(+paid||0))<=.009;
 const pendingOwn=own.filter(r=>!isPaid(r.valor,r.recebido)),paidOwn=own.filter(r=>isPaid(r.valor,r.recebido));
 const pendingShared=shared.filter(r=>!isPaid(r.p.valor,r.p.pago)),paidShared=shared.filter(r=>isPaid(r.p.valor,r.p.pago));
 const pendingTotal=pendingOwn.reduce((n,r)=>n+Math.max(0,(+r.valor||0)-(+r.recebido||0)),0)+pendingShared.reduce((n,r)=>n+Math.max(0,(+r.p.valor||0)-(+r.p.pago||0)),0);
 const status=(total,paid)=>{const left=Math.max(0,(+total||0)-(+paid||0));return left<=.009?'Quitado':(+paid||0)>0?'Parcial':'Pendente'};
 const ownRows=rows=>rows.map(r=>{const left=Math.max(0,(+r.valor||0)-(+r.recebido||0)),st=status(r.valor,r.recebido);return '<article class="receivable-row"><div><b>'+esc(r.nome)+'</b><small>'+esc(r.descricao||'Dívida cadastrada')+(r.data?' · '+esc(r.data):'')+'</small></div><strong>'+brl(left)+'</strong><span class="shared-status status-'+st.toLowerCase()+'">'+st+'</span><div class="receivable-actions"><button class="button text" data-action="edit-receivable" data-id="'+esc(r.id)+'">Editar dados</button>'+(left>.009?'<button class="button text" data-action="pay-receivable" data-id="'+esc(r.id)+'">Registrar pagamento</button>':'')+'<button class="button text danger" data-action="delete-receivable" data-id="'+esc(r.id)+'">Excluir</button></div></article>'}).join('');
 const sharedRows=rows=>rows.map(r=>{const left=Math.max(0,(+r.p.valor||0)-(+r.p.pago||0)),st=status(r.p.valor,r.p.pago);return '<article class="receivable-row"><div><b>'+esc(r.p.nome)+'</b><small>'+esc(r.x.nome)+' · '+esc(r.k)+' · Devido '+brl(r.p.valor)+' · Recebido '+brl(r.p.pago||0)+'</small></div><strong>'+brl(left)+'</strong><span class="shared-status status-'+st.toLowerCase()+'">'+st+'</span><div class="receivable-actions"><button class="button text" data-action="shared-detail" data-id="'+esc(r.x.id)+'">Abrir rateio</button><button class="button text" data-action="shared-edit-person" data-id="'+esc(r.x.id)+'" data-person="'+r.i+'">Editar todos os dados</button>'+(left>.009?'<button type="button" class="button text" data-action="shared-payment" data-id="'+esc(r.x.id)+'" data-person="'+r.i+'">Registrar recebimento</button>':'')+'</div></article>'}).join('');
 const paid=receivablesTab==='quitados',ownRowsHtml=ownRows(paid?paidOwn:pendingOwn),sharedRowsHtml=sharedRows(paid?paidShared:pendingShared);
 return head('RECEBÍVEIS','Quem me deve','Acompanhe os valores que ainda faltam receber e consulte os pagamentos concluídos quando precisar.',button('＋ Cadastrar dívida','new-receivable','primary'))+
 '<div class="metrics">'+metric('Total pendente',brl(pendingTotal),'Somente valores que ainda faltam receber','red')+metric('Pessoas com saldo pendente',String(pendingOwn.length+pendingShared.length),'Dívidas avulsas e participantes de rateios')+metric('Já quitaram',String(paidOwn.length+paidShared.length),'Disponíveis na aba de quitados','green')+'</div>'+
 '<div class="receivables-tabs" role="tablist" aria-label="Situação dos recebimentos"><button type="button" role="tab" aria-selected="'+(!paid)+'" class="'+(!paid?'is-active':'')+'" data-action="receivables-tab" data-tab="pendentes">Em aberto <span>'+(pendingOwn.length+pendingShared.length)+'</span></button><button type="button" role="tab" aria-selected="'+paid+'" class="'+(paid?'is-active':'')+'" data-action="receivables-tab" data-tab="quitados">Quem já pagou <span>'+(paidOwn.length+paidShared.length)+'</span></button></div>'+
 '<section class="panel"><div class="panel-head"><div><h2>'+(paid?'Recebimentos concluídos':'Dívidas em aberto')+'</h2><p>'+(paid?'Pessoas que já quitaram totalmente o valor combinado.':'Aqui aparecem somente pessoas que ainda têm algum valor pendente.')+'</p></div></div><div class="receivable-list">'+(ownRowsHtml||'<p class="empty">'+(paid?'Nenhuma dívida avulsa quitada.':'Nenhuma dívida avulsa pendente.')+'</p>')+'</div></section>'+
 '<section class="panel receivables-shared-panel"><div class="panel-head"><div><p class="eyebrow">INTEGRAÇÃO AUTOMÁTICA</p><h2>'+(paid?'Rateios quitados':'Dívidas compartilhadas')+'</h2><p>'+(paid?'Participantes de rateios que já pagaram integralmente.':'Participantes dos rateios aparecem aqui sem criar uma segunda dívida.')+'</p></div></div><div class="receivable-list">'+(sharedRowsHtml||'<p class="empty">'+(paid?'Nenhum participante quitado.':'Nenhum participante com valor pendente nos rateios.')+'</p>')+'</div></section>';
}
function receivableForm(id){
 const r=(S.receivables||[]).find(x=>x.id===id); if(id&&!r)return;
 openForm(r?'Editar dívida':'Cadastrar quem me deve',[{name:'nome',label:'Nome da pessoa',required:true},{name:'descricao',label:'Descrição / motivo'},{name:'valor',label:'Valor total devido (R$)',type:'number',min:.01,step:'.01',required:true},{name:'recebido',label:'Valor já recebido (R$)',type:'number',min:0,step:'.01',required:true},{name:'data',label:'Data do combinado',type:'date'},{name:'observacao',label:'Observações',type:'textarea'}],r||{valor:0,recebido:0,data:new Date().toISOString().slice(0,10)},v=>{const total=+v.valor||0,paid=+v.recebido||0;if(!v.nome.trim()||total<=0||paid>total){appToast('Confira o nome e os valores informados.','error');return false}if(r)Object.assign(r,{nome:v.nome.trim(),descricao:v.descricao||'',valor:total,recebido:paid,data:v.data||'',observacao:v.observacao||''});else S.receivables.push({id:'rcv-'+Date.now(),nome:v.nome.trim(),descricao:v.descricao||'',valor:total,recebido:paid,data:v.data||'',observacao:v.observacao||''});save();render()});
}
function payReceivable(id){
 const r=S.receivables.find(x=>x.id===id);if(!r)return;const left=Math.max(0,(+r.valor||0)-(+r.recebido||0));
 openForm('Registrar pagamento · '+r.nome,[{name:'valor',label:'Valor recebido (R$)',type:'number',min:.01,max:left,step:'.01',required:true},{name:'data',label:'Data do recebimento',type:'date',required:true},{name:'forma',label:'Forma de recebimento',type:'select',options:[{value:'pix',label:'Pix / transferência'},{value:'dinheiro',label:'Dinheiro em espécie'}]},{name:'bancoId',label:'Conta que recebeu',type:'select',options:[{value:'',label:'Selecione a conta'},...S.banks.map(b=>({value:b.id,label:b.nome}))],showIf:{field:'forma',value:'pix'}}],{valor:left,data:new Date().toISOString().slice(0,10),forma:'pix',bancoId:''},v=>{const amount=+v.valor||0;if(amount<=0||amount>left+.001)return false;if(v.forma==='pix'&&!v.bancoId){appToast('Selecione a conta que recebeu.','error');return false}r.recebido=(+r.recebido||0)+amount;S.movements.push({id:'mv'+Date.now(),nome:'Recebimento de dívida — '+r.nome,valor:amount,data:v.data,bancoId:v.forma==='pix'?v.bancoId:'',tipo:'Reembolso',includeInBalance:true,receivableId:id,formaRecebimento:v.forma});save();render()});
}
function removeSharedPerson(id,index){
 const found=findSharedExpense(id);if(!found)return;const x=found.expense,p=x.participantes[index];if(!p||!confirm('Excluir '+p.nome+' deste rateio e os recebimentos vinculados?'))return;
 S.movements=S.movements.filter(m=>!(m.sharedExpenseId===id&&m.sharedPersonIndex===index));
 S.movements.forEach(m=>{if(m.sharedExpenseId===id&&Number.isInteger(m.sharedPersonIndex)&&m.sharedPersonIndex>index)m.sharedPersonIndex--});
 x.participantes.splice(index,1);x.valor=(+x.minhaParte||0)+x.participantes.reduce((n,z)=>n+(+z.valor||0),0);save();const dialog=document.querySelector('.shared-expense-dialog');closeDialogThen(dialog,()=>{render();sharedExpenseDetail(id)});
}
function entryFields(){return [{name:'nome',label:'Descrição da entrada',required:true},{name:'valor',label:'Valor recebido (R$)',type:'number',min:0.01,step:'.01',required:true},{name:'data',label:'Data do recebimento',type:'date',required:true},{name:'bancoId',label:'Onde recebeu?',type:'select',options:[{value:'__cash__',label:'Dinheiro em espécie'},...S.banks.map(b=>({value:b.id,label:b.nome}))]},{name:'tipo',label:'Origem',type:'select',options:['Salário','Bônus','Vale-refeição','Vale-alimentação','Auxílio home office','Reembolso','Reembolso de despesa compartilhada','Transferência','Rendimento de investimento','Outra entrada']},{name:'includeInBalance',label:'Considerar esta entrada no saldo disponível?',type:'checkbox'},{name:'observacao',label:'Observações'}]}
function newBonus(k){openForm('Adicionar bônus ou extra',[{name:'descricao',label:'Descrição do bônus ou extra',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'data',label:'Data do recebimento',type:'date',required:true},{name:'includeInBalance',label:'Considerar esta entrada no saldo disponível?',type:'checkbox'},{name:'observacao',label:'Observações'}],{valor:0,data:k+'-01',includeInBalance:true},v=>{let month=String(v.data||'').slice(0,7);if(!month)return false;let id='bx'+Date.now(),mid='mv'+Date.now(),item={id,descricao:v.descricao,valor:+v.valor||0,data:v.data,observacao:v.observacao,includeInBalance:v.includeInBalance==='1',movementId:mid};M(month).bonusItems.push(item);S.movements.push({id:mid,nome:v.descricao,valor:+v.valor||0,data:v.data,bancoId:'',tipo:'Bônus',includeInBalance:v.includeInBalance==='1',observacao:v.observacao,bonusItemId:id});if(!S.keys.includes(month))S.keys.push(month);S.keys.sort();save()})}
function editBonus(k,i){let m=M(k),x=(m.bonusItems||[])[i];if(!x)return;openForm('Editar bônus ou extra',[{name:'descricao',label:'Descrição',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'data',label:'Data do recebimento',type:'date',required:true},{name:'includeInBalance',label:'Considerar esta entrada no saldo disponível?',type:'checkbox'},{name:'observacao',label:'Observações'}],{...x,includeInBalance:x.includeInBalance!==false},v=>{Object.assign(x,v,{valor:+v.valor||0,includeInBalance:v.includeInBalance==='1'});let z=S.movements.find(y=>y.id===x.movementId);if(z)Object.assign(z,{nome:v.descricao,valor:+v.valor||0,data:v.data,includeInBalance:v.includeInBalance==='1'});let next=String(v.data||'').slice(0,7);if(next&&next!==k){m.bonusItems=m.bonusItems.filter(y=>y!==x);M(next).bonusItems.push(x);if(!S.keys.includes(next))S.keys.push(next);S.keys.sort()}save()})}
function deleteBonus(k,i){let m=M(k),item=m.bonusItems?.[i];if(!item||!confirm('Excluir este bônus ou extra?'))return;m.bonusItems.splice(i,1);if(item.movementId)S.movements=S.movements.filter(x=>x.id!==item.movementId);save();render()}
