function bankMovementSummary(k){let m=M(k),items=[...(m.gastos||[]),...(m.fixos||[]),...(m.parcelas||[])].filter(x=>x.tipo!=='Dinheiro'&&x.bancoId!=='__cash__'),by=S.banks.map(b=>{let incoming=(S.movements||[]).filter(x=>x.bancoId===b.id&&String(x.data||'').slice(0,7)===k).reduce((n,x)=>n+(+x.valor||0),0),outgoing=items.filter(x=>x.bancoId===b.id).reduce((n,x)=>n+(+x.valor||0),0);return{b,incoming,outgoing,net:incoming-outgoing}}).filter(x=>x.incoming||x.outgoing);return '<section class="panel bank-movement-summary"><div class="panel-head"><div><h2>Movimentações por banco</h2><p>Entradas registradas e despesas associadas a cada conta.</p></div><button class="button text" data-action="go-entradas">＋ Entradas</button></div>'+(by.length?by.map(x=>'<div class="bank-movement-row"><span class="bank-movement-brand" style="--bank-color:'+esc(x.b.cor||bankColor(x.b.nome))+'">'+esc(String(x.b.nome||'?').trim().charAt(0).toLocaleUpperCase('pt-BR')||'?')+'</span><div class="bank-movement-name"><b>'+esc(x.b.nome)+'</b><small>Entradas '+brl(x.incoming)+' · Saídas '+brl(x.outgoing)+'</small></div><strong class="'+(x.net<0?'text-red':'text-green')+'">'+brl(x.net)+'</strong></div>').join(''):'<p class="empty">Associe despesas aos bancos e registre entradas para ver a movimentação por conta.</p>')+'</section>'}
