function newSubscription(){let start=S.keys.includes(cur)?cur:today;openForm('Nova assinatura',[{name:'nome',label:'Nome da despesa recorrente',required:true},{name:'valor',label:'Valor (R$)',type:'number',min:0,step:'.01',required:true},{name:'regraVencimento',label:'Quando vence?',type:'select',options:[{value:'dia-fixo',label:'Dia fixo do mês'},{value:'5º dia útil',label:'5º dia útil do mês'}]},{name:'dia',label:'Dia da cobrança (se fixo)',type:'number',min:1,max:31,step:1,required:true,showIf:{field:'regraVencimento',value:'dia-fixo'}},{name:'tipo',label:'Forma de pagamento',type:'select',options:['Débito','Crédito','Pix','Dinheiro','Alimentação / Refeição','Auxílio']},{name:'cat',label:'Categoria'},{name:'inicio',label:'Começa em qual mês?',type:'month',required:true},{name:'observacao',label:'Observações',type:'textarea'}],{valor:0,dia:5,regraVencimento:'dia-fixo',tipo:'Débito',cat:'Assinaturas',inicio:start},v=>{let sub={id:'s'+Date.now(),nome:v.nome,valor:+v.valor||0,dia:+v.dia||5,regraVencimento:v.regraVencimento||'dia-fixo',tipo:v.tipo||'Débito',cat:v.cat||'Assinaturas',observacao:v.observacao,ativo:true,inicio:v.inicio};S.subscriptions.push(sub);let [y,mo]=v.inicio.split('-').map(Number);[0,1].forEach(offset=>{let dt=new Date(y,mo-1+offset,1),k=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0'),m=M(k);if(!m.fixos.some(x=>x.subscriptionId===sub.id))m.fixos.push({nome:sub.nome,dia:subscriptionDueDay(dt.getFullYear(),dt.getMonth(),sub),tipo:sub.tipo,cat:sub.cat,valor:sub.valor,pago:false,subscriptionId:sub.id,regraVencimento:sub.regraVencimento})});save()})}
