function openSpendingAdvisor(){
 let prefs=S.preferences||{},assistantName=(prefs.assistantName||'Theo').trim()||'Theo',assistantGender=prefs.assistantGender||'masculino',assistantLabel=assistantGender==='feminino'?'ASSISTENTE FINANCEIRA':'ASSISTENTE FINANCEIRO',displayName=S.profile?.chamado||S.profile?.nome||'',hour=new Date().getHours(),greeting=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';
 let old=document.getElementById('spending-advisor');if(old)old.remove();let d=document.createElement('dialog');d.id='spending-advisor';d.className='finance-dialog advisor-dialog advisor-chat-dialog';
 let k=S.keys.includes(cur)?cur:(S.keys.includes(today)?today:S.keys[S.keys.length-1]),answers={item:'',valor:0,cat:'',tipo:'',essencial:'',prazo:'',parcelas:1};
 d.innerHTML='<div class="dialog-head"><div><p class="eyebrow">'+assistantLabel+'</p><h2>'+esc(assistantName)+'</h2><small>Planejamento e decisões com base nos seus dados</small></div><button class="button secondary" data-close>×</button></div><div class="advisor-chat-intro">'+greeting+(displayName?', '+esc(displayName):'')+'! Sou '+esc(assistantName)+'. Conte sua ideia do seu jeito; pode informar várias coisas na mesma mensagem.</div><div class="advisor-chat-messages" aria-live="polite"></div><form class="advisor-chat-reply"><input name="message" type="text" autocomplete="off" placeholder="Escreva sua mensagem..." required><button class="button primary" type="submit">Enviar</button></form>';
 document.body.appendChild(d);let messages=d.querySelector('.advisor-chat-messages'),reply=d.querySelector('.advisor-chat-reply');
 const bubble=(who,html)=>{let el=document.createElement('div');el.className='advisor-chat-bubble '+(who==='user'?'user':'assistant');el.innerHTML=html;messages.appendChild(el);messages.scrollTop=messages.scrollHeight};
 const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const parseMoney=s=>{let raw=String(s),m=raw.match(/r\$\s*(\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?|\d+(?:,\d{1,2})?)/i)||raw.match(/(\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?|\d+(?:,\d{1,2})?)\s*(?:reais|real)\b/i);if(!m){let clean=raw.replace(/\b\d{1,2}\s*(?:x|vezes|parcelas?)\b/ig,' ');m=clean.match(/\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?|\d+(?:,\d{1,2})?/i)}if(!m)return 0;let value=Array.isArray(m)?m[m.length-1]:m[0];if(m.length>1)value=m[1];return Math.max(0,+String(value).replace(/\./g,'').replace(',','.')||0)};
 const parse=message=>{
  let t=norm(message),amount=parseMoney(message);if(amount>0&&!answers.valor)answers.valor=amount;
  let installments=t.match(/(\d{1,2})\s*(?:x|vezes|parcelas?)/);if(installments)answers.parcelas=Math.max(1,+installments[1]||1);else if(/\b(duas|dois)\s+vezes\b/.test(t))answers.parcelas=2;else if(/\b(tres|tr[eê]s)\s+vezes\b/.test(t))answers.parcelas=3;
  if(/cartao|credito|parcelad/.test(t))answers.tipo='Crédito';else if(/pix/.test(t))answers.tipo='Pix';else if(/debito/.test(t))answers.tipo='Débito';else if(/boleto/.test(t))answers.tipo='Boleto';else if(/dinheiro|especie/.test(t))answers.tipo='Dinheiro';else if(/vale.refeicao|alimentacao/.test(t))answers.tipo='Alimentação / Refeição';
  if(/nao e urgente|nao urgente|posso esperar|pode esperar|superfluo/.test(t))answers.essencial='nao';else if(/essencial|necessari|preciso|urgente|indispensavel/.test(t))answers.essencial='sim';
  if(/daqui a 3|tres meses/.test(t))answers.prazo='tres';else if(/proximo mes|mes que vem/.test(t))answers.prazo='proximo';else if(/agora|hoje|imediat/.test(t))answers.prazo='agora';else if(/pode esperar|nao urgente/.test(t))answers.prazo='proximo';
  let cat=(S.cats||[]).find(x=>t.includes(norm(x)));if(cat)answers.cat=cat;
  if(!answers.cat){let map=[[/roupa|vestuario|calcado/,'Vestuário'],[/mercado|comida|restaurante|aliment/,'Alimentação'],[/gasolina|combustivel|moto|transporte/,'Transporte'],[/remedio|consulta|medico|saude/,'Saúde'],[/curso|faculdade|livro|educacao/,'Educação'],[/assinatura|streaming/,'Assinaturas'],[/aluguel|moradia|casa/,'Moradia']];let hit=map.find(x=>x[0].test(t));if(hit)answers.cat=(S.cats||[]).find(x=>norm(x).includes(norm(hit[1]))||norm(hit[1]).includes(norm(x)))||hit[1]}
  if(!answers.item){let item=t.replace(/^\s*(eu\s+)?(quero|pretendo|estou pensando|vou)\s+(comprar|em comprar)\s*/i,'').replace(/(?:r\$\s*)?\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?\s*(?:reais|real)?/i,'').replace(/\b(no cartao|cartao de credito|credito|pix|debito|boleto|em \d+ vezes|em (?:duas|dois|tres) vezes|\d+x|nao urgente|nao e urgente)\b/ig,'').replace(/\s+/g,' ').replace(/[\s,.;]+$/,'').replace(/\bde$/,'').trim();if(item&&item.length>1&&!/^\d/.test(item))answers.item=item.slice(0,100)}
 };
 const missing=()=>{if(!answers.item)return ['O que você está pensando em comprar?','Pode me contar o que é. Se quiser, já informe o valor e como pretende pagar.'];if(!(answers.valor>0))return ['Quanto você pretende gastar?','Pode informar o valor aproximado em reais.'];if(!answers.cat)return ['Em qual categoria essa compra entra?','Ex.: alimentação, transporte, saúde, educação, vestuário ou outra categoria.'];if(!answers.tipo)return ['Como pretende pagar?','Pode ser Pix, débito, crédito, boleto ou dinheiro. Se for crédito, informe também o número de parcelas.'];if(!answers.essencial)return ['Essa compra é necessária neste momento?','Quero entender se é essencial ou se pode esperar.'];if(!answers.prazo)return ['Quando pretende fazer essa compra?','Agora, no próximo mês ou mais adiante?'];return null};
 const finish=()=>{
  let c=k?calc(k):{saldo:0,beneficiosRestantes:{alimentacao:0}},amount=+answers.valor||0,parts=Math.max(1,+answers.parcelas||1),monthly=answers.tipo==='Crédito'?amount/parts:amount,available=c.saldo||0,usesBenefit=['Alimentação / Refeição','Vale-refeição / alimentação'].includes(answers.tipo),benefit=usesBenefit?(c.beneficiosRestantes?.alimentacao||0):0,base=usesBenefit?benefit:available,room=base-monthly,hasDebt=S.debts.some(x=>(+x.valor||0)>0),verdict,explain;
  if(usesBenefit&&amount>benefit){verdict='REVISE O VALOR';explain='O benefício disponível estimado é '+brl(benefit)+'. Confira se a compra pode ser coberta integralmente por ele.'}
  else if(room<0){verdict=answers.essencial==='sim'?'BUSQUE UMA ALTERNATIVA MAIS BARATA':'MELHOR ADIAR';explain='Considerando o saldo projetado de '+brl(base)+', o compromisso desta compra deixaria uma diferença de '+brl(Math.abs(room))+'.'}
  else if(answers.essencial==='nao'&&room<Math.max(100,base*.2)){verdict='PODE CABER, MAS COM CAUTELA';explain='A compra deixaria aproximadamente '+brl(room)+' de margem no cenário atual.'}
  else{verdict='CABE NO CENÁRIO ATUAL';explain='Após considerar '+brl(monthly)+' neste mês, restariam aproximadamente '+brl(room)+'. Confirme se todas as contas e despesas já foram registradas.'}
  if(hasDebt)explain+=' Você possui dívidas em aberto; compare esta compra com os vencimentos e os juros antes de decidir.';
  if(answers.prazo!=='agora')explain+=' Como a compra pode esperar, atualize a projeção do mês em que pretende realizá-la antes de assumir o compromisso.';
  bubble('assistant','<b>Análise de '+esc(answers.item)+'</b><div class="advisor-chat-verdict">'+verdict+'</div><p>'+esc(explain)+'</p><div class="advisor-analysis-facts"><span>Valor total: <b>'+brl(amount)+'</b></span><span>Pagamento: <b>'+esc(answers.tipo)+'</b></span><span>Parcelas: <b>'+parts+' × '+brl(monthly)+'</b></span><span>Categoria: <b>'+esc(answers.cat)+'</b></span><span>Necessidade: <b>'+(answers.essencial==='sim'?'Essencial':'Pode esperar')+'</b></span></div><small>Análise estimada com base em '+esc(k?full(k):'seus dados cadastrados')+'. Não inclui despesas ainda não registradas, juros desconhecidos ou limite disponível do cartão.</small>');
  reply.innerHTML='<input name="message" type="text" placeholder="Quer analisar outra compra?" autocomplete="off"><button class="button primary" type="button" data-restart>Nova análise</button>';reply.querySelector('[data-restart]').onclick=()=>{answers={item:'',valor:0,cat:'',tipo:'',essencial:'',prazo:'',parcelas:1};messages.innerHTML='';bubble('assistant','Vamos começar uma nova análise. Pode me contar tudo em uma única mensagem.');reply.innerHTML='<input name="message" type="text" placeholder="Ex.: roupa de R$ 250 no crédito em 2 vezes" required><button class="button primary" type="submit">Enviar</button>';reply.querySelector('input').focus()};
 };
 const next=()=>{let q=missing();if(!q){finish();return}bubble('assistant','<b>'+esc(q[0])+'</b><small>'+esc(q[1])+'</small>')};
 bubble('assistant','Olá'+(displayName?', '+esc(displayName):'')+'! Sou '+esc(assistantName)+'. Pode me contar sua ideia em uma mensagem só; vou aproveitar todas as informações que você já fornecer.');
 reply.onsubmit=e=>{e.preventDefault();let input=reply.querySelector('[name=message]'),message=(input?.value||'').trim();if(!message)return;bubble('user',esc(message));input.value='';parse(message);if(!answers.item&&!answers.valor)answers.item=message.slice(0,100);next()};
 d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();reply.querySelector('input').focus();
}

const investmentFormat=n=>(+n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
async function refreshInvestmentRates(force=false){
 const key='financas.investmentRates.v1',now=Date.now();
 try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(!force&&saved&&now-saved.fetchedAt<86400000){investmentRates={...saved,error:false};if(cur==='investimentos')render();return}
 const get=async(code)=>{const u='https://api.bcb.gov.br/dados/serie/bcdata.sgs.'+code+'/dados/ultimos/2?formato=json';const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw new Error('BCB indisponível');const a=await r.json();const x=a[a.length-1];if(!x)throw new Error('Sem dados');return{value:+String(x.valor).replace(',','.'),date:x.data}};
 const [selic,cdi,ipca]=await Promise.all([get(432),get(4389),get(433)]);
 investmentRates={selic,cdi,ipca,updated:new Date().toISOString(),fetchedAt:now,error:false};localStorage.setItem(key,JSON.stringify(investmentRates));
 }catch(e){const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved)investmentRates={...saved,error:true};else investmentRates={...investmentRates,error:true}}
 if(cur==='investimentos')render();
}
function investmentTax(days){return days<=180?.225:days<=360?.20:days<=720?.175:.15}
function investmentProjection(){
 const amount=Math.max(0,+($('#inv-amount')?.value||1000)),months=Math.max(1,+($('#inv-months')?.value||12)),pct=Math.max(1,+($('#inv-cdi')?.value||100));
 const cdi=investmentRates.cdi?.value||0,selic=investmentRates.selic?.value||0,days=months*365/12,ir=investmentTax(days);
 const calc=(annual)=>{const gross=amount*Math.pow(1+annual/100,months/12)-amount;return{gross,net:gross*(1-ir)}};
 const c=calc(cdi*pct/100),t=calc(selic),p=amount*(Math.pow(1+(selic>8.5?.005:(selic*.7/100/12)),months)-1);
 return{amount,months,cdi,pct,selic,cdiResult:c,tesouro:t,poupanca:p,ir};
}
function updateInvestmentProjection(){const o=$('#investment-results');if(!o)return;const x=investmentProjection();o.innerHTML='<div class="investment-result"><span>CDB · '+x.pct+'% do CDI</span><strong>'+investmentFormat(x.amount+x.cdiResult.net)+'</strong><small>Ganho líquido estimado: '+investmentFormat(x.cdiResult.net)+'</small></div><div class="investment-result"><span>Tesouro Selic · estimativa</span><strong>'+investmentFormat(x.amount+x.tesouro.net)+'</strong><small>Ganho líquido estimado: '+investmentFormat(x.tesouro.net)+'</small></div><div class="investment-result"><span>Poupança · estimativa simplificada</span><strong>'+investmentFormat(x.amount+x.poupanca)+'</strong><small>Ganho estimado: '+investmentFormat(x.poupanca)+'</small></div><p class="investment-note">Estimativas brutas de premissas constantes. CDB e Tesouro usam IR regressivo estimado; Tesouro considera Selic constante e não inclui custódia, spread ou marcação a mercado. Poupança usa a regra simplificada de remuneração básica, sem TR. Não são ofertas nem garantia de retorno.</p>'}
function investmentsView(){
 const rate=(x,suffix='% a.a.')=>x?x.value.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+suffix:'—';
 const date=x=>x?.date||'Aguardando dado';
 const freshness=investmentRates.updated?'Atualizado em '+new Date(investmentRates.updated).toLocaleString('pt-BR'):(investmentRates.error?'Não foi possível consultar a fonte':'Consultando fontes oficiais…');
 const view=head('INVESTIMENTOS','Investir com informação.','Compare cenários, entenda os riscos e simule antes de decidir.',button('↻ Atualizar dados','refresh-investments','secondary'))+
 '<section class="investment-status"><div><b>Dados de referência</b><span>'+esc(freshness)+'</span></div><span class="investment-live">'+(investmentRates.error?'Último dado disponível / falha na consulta':'Atualização automática diária')+'</span></section>'+
 '<section class="investment-indicators"><article><span>Meta Selic</span><strong>'+(investmentRates.selic?rate(investmentRates.selic):'—')+'</strong><small>Referência: '+date(investmentRates.selic)+'</small></article><article><span>CDI</span><strong>'+(investmentRates.cdi?rate(investmentRates.cdi):'—')+'</strong><small>Referência: '+date(investmentRates.cdi)+'</small></article><article><span>IPCA mensal</span><strong>'+(investmentRates.ipca?rate(investmentRates.ipca,'%'):'—')+'</strong><small>Referência: '+date(investmentRates.ipca)+'</small></article></section>'+
 '<section class="panel investment-calculator"><div class="panel-head"><div><p class="eyebrow">SIMULADOR</p><h2>Quanto seu dinheiro pode render?</h2><p>Altere o valor e o prazo para comparar cenários.</p></div></div><div class="investment-fields"><label>Valor inicial (R$)<input id="inv-amount" data-change="investment-input" type="number" min="1" step="0.01" value="1000"></label><label>Prazo (meses)<input id="inv-months" data-change="investment-input" type="number" min="1" max="600" value="12"></label><label>CDB (% do CDI)<input id="inv-cdi" data-change="investment-input" type="number" min="1" max="300" value="100"></label></div><div id="investment-results" class="investment-results"></div></section>'+
 '<section class="panel"><div class="panel-head"><div><p class="eyebrow">COMO ANALISAR</p><h2>Não olhe só para a rentabilidade</h2></div></div><div class="investment-risk-grid"><article><b>Liquidez</b><p>Quando você pode resgatar? Liquidez diária não é a mesma coisa que vencimento longo.</p></article><article><b>Risco de crédito</b><p>Quem deve pagar? CDB, LCI e LCA podem ter cobertura do FGC dentro dos limites e regras vigentes; fundos e títulos públicos têm riscos diferentes.</p></article><article><b>Impostos e custos</b><p>Compare o rendimento líquido, considerando IR, IOF, custódia, taxas e prazo.</p></article><article><b>Objetivo e prazo</b><p>Dinheiro da reserva de emergência pede acesso e estabilidade, não apenas uma taxa maior.</p></article></div></section>'+
 '<section class="panel investment-learning"><div class="panel-head"><div><p class="eyebrow">GUIA PARA COMEÇAR</p><h2>Entenda antes de investir</h2><p>Um pequeno dicionário para quem está começando.</p></div></div><div class="investment-learning-grid"><article><b>Selic</b><p>É a taxa básica de juros da economia brasileira, definida pelo Copom. Ela influencia o custo do crédito e a rentabilidade de vários investimentos de renda fixa.</p></article><article><b>CDI</b><p>É uma taxa de referência muito próxima da Selic, usada para comparar investimentos. Quando um CDB paga 100% do CDI, sua remuneração acompanha essa referência, conforme as regras do produto.</p></article><article><b>IPCA</b><p>É o índice oficial de inflação ao consumidor. Ele mede como os preços variam e ajuda a entender se o rendimento está preservando seu poder de compra.</p></article><article><b>CDB</b><p>É um título emitido por um banco. Você empresta dinheiro à instituição e recebe juros. Confira taxa, vencimento, liquidez e risco do emissor. CDB elegível pode contar com cobertura do FGC, dentro dos limites e regras.</p></article><article><b>Tesouro Direto</b><p>É um programa de compra e venda de títulos públicos federais. Tesouro Selic costuma ser usado para objetivos de curto prazo, mas pode ter custos e regras de resgate; outros títulos oscilam de preço antes do vencimento.</p></article><article><b>Poupança</b><p>É uma aplicação simples e isenta de IR para pessoa física, com rendimento definido por regra legal. Compare sempre com alternativas de risco e liquidez semelhantes.</p></article><article><b>Liquidez</b><p>Indica a facilidade e o prazo para transformar o investimento em dinheiro disponível. Liquidez diária não significa necessariamente resgate instantâneo ou em qualquer horário.</p></article><article><b>FGC</b><p>O Fundo Garantidor de Créditos protege determinados produtos e depósitos elegíveis, respeitando limites por CPF/CNPJ e instituição ou conglomerado. Não cobre todo tipo de investimento.</p></article><article><b>Rendimento bruto e líquido</b><p>O bruto é antes de impostos e custos. O líquido é o que sobra depois deles. Para comparar opções, olhe o líquido e considere também a inflação.</p></article></div><p class="investment-note">Comece entendendo seu objetivo e mantendo uma reserva de emergência acessível. Nenhuma taxa isolada garante que um investimento seja adequado para você.</p></section>'+'<section class="investment-sources"><b>Fontes e metodologia</b><p>Indicadores consultados automaticamente no Sistema Gerenciador de Séries Temporais do Banco Central. Atualização ao abrir a área, no máximo uma vez a cada 24 horas; atualização manual disponível. As séries podem ter datas de referência diferentes.</p><a href="https://dadosabertos.bcb.gov.br/dataset/432-taxa-de-juros---meta-selic-definida-pelo-copom" target="_blank" rel="noopener">Banco Central · Meta Selic</a><a href="https://dadosabertos.bcb.gov.br/" target="_blank" rel="noopener">Banco Central · Dados abertos</a><a href="https://data.anbima.com.br/" target="_blank" rel="noopener">ANBIMA Data · consulta de ativos</a><p>Esta primeira versão não lista ofertas comerciais de CDB/LCI/LCA em tempo real. A taxa de CDB é um campo de simulação, não uma oferta verificada. Dados não são recomendação personalizada.</p></section>';
 setTimeout(updateInvestmentProjection,0);return view;
}

let decisionSim={debtId:'',extraPayment:0,priorityDebtId:'',interest:0,amount:500,months:12,monthlySaving:0,purchaseAmount:500,purchaseParts:2,financePrincipal:10000,financeDownPayment:0,financeRate:1.5,financeMonths:12,incomeCurrent:0,incomeNew:0,incomeExtraCost:0};
function money(n){return privacyVisible?brl(n):'••••••'}
function financialInsightsView(){
 let keys=[...S.keys].sort(),rows=keys.map(k=>({k,...calc(k)})),currentKey=keys.includes(today)?today:keys[keys.length-1],current=currentKey?calc(currentKey):null,idx=keys.indexOf(currentKey),previous=idx>0?calc(keys[idx-1]):null,budgets=S.preferences?.categoryBudgets||{},debt=S.debts.reduce((n,d)=>n+(+d.valor||0),0),alerts=[];
 let monthSpent=current?.cats||{},spent={};rows.forEach(r=>Object.entries(r.cats||{}).forEach(([cat,v])=>spent[cat]=(spent[cat]||0)+v));
 Object.entries(budgets).forEach(([cat,limit])=>{let v=monthSpent[cat]||0,p=limit?v/limit*100:0;if(p>=70)alerts.push({level:p>=100?'high':'mid',title:p>=100?'Limite ultrapassado: '+cat:'Atenção ao limite: '+cat,desc:money(v)+' utilizados de '+money(limit)+'.'});});
 rows.filter(r=>r.saldo<0).forEach(r=>alerts.push({level:'high',title:'Saldo projetado negativo',desc:full(r.k)+' apresenta saldo de '+money(r.saldo)+'.'}));
 if(debt>0)alerts.push({level:'mid',title:'Dívidas em acompanhamento',desc:S.debts.filter(d=>d.valor>0).length+' compromisso(s) com saldo devedor. Compare juros e vencimentos.'});
 if(!current)alerts.push({level:'mid',title:'Complete seus dados',desc:'Cadastre entradas e despesas para habilitar diagnósticos mais precisos.'});
 if(!alerts.length)alerts.push({level:'ok',title:'Nenhum alerta identificado',desc:'Continue registrando suas movimentações para manter as análises atualizadas.'});
 let income=current?(current.salario+current.extras+current.beneficios.reembolso):0,out=current?current.caixaDespesas:0,net=current?current.saldo:0,ratio=income?out/income*100:0;
 let essentialCats=Object.entries(monthSpent).filter(([cat])=>/moradia|alimenta|saude|transporte|energia|agua|luz|gas|internet|telefone|educacao/i.test(cat)),essential=essentialCats.reduce((n,x)=>n+x[1],0)||out;
 let reserveMonths=Math.min(24,Math.max(1,+S.preferences?.emergencyReserveMonths||6)),reserveTarget=essential*reserveMonths,reserveBalance=Math.max(0,+S.preferences?.emergencyReserveBalance||0),reservePct=reserveTarget?Math.min(100,reserveBalance/reserveTarget*100):0;
 let debtPressure=income?Math.min(100,debt/income*10):0,spendingScore=income?Math.max(0,100-Math.max(0,ratio-50)*1.1):35,reserveScore=reserveTarget?Math.min(100,reservePct):0,stabilityScore=rows.length?Math.max(0,100-rows.filter(r=>r.saldo<0).length/rows.length*100):35;
 let health=Math.round(Math.max(0,Math.min(100,spendingScore*.35+reserveScore*.3+stabilityScore*.25+(100-debtPressure)*.1))),healthLabel=health>=80?'Boa organização':health>=60?'Em desenvolvimento':health>=40?'Atenção necessária':'Requer atenção';
 let top=Object.entries(monthSpent).sort((a,b)=>b[1]-a[1]).slice(0,5),opportunities=top.filter(x=>x[1]>0).slice(0,3).map(x=>({cat:x[0],value:x[1]*.1})),delta=previous?net-previous.saldo:null,completedGoals=(S.goals||[]).filter(g=>g.concluida||g.status==='Concluída'||(+g.valorAlvo>0&&(+g.valorAtual||0)>=(+g.valorAlvo||0))).length,achievements=[];
 if(keys.length>=3)achievements.push('Três ou mais meses acompanhados');if(S.debts.length&&S.debts.every(d=>(+d.valor||0)<=0))achievements.push('Todas as dívidas cadastradas foram quitadas');if(completedGoals)achievements.push(completedGoals+' objetivo(s) concluído(s)');if(current&&current.saldo>=0)achievements.push('Saldo mensal projetado positivo');if(!achievements.length)achievements.push('Registre suas movimentações para desbloquear conquistas');
 return head('INTELIGÊNCIA FINANCEIRA','Entenda seus números.','Uma leitura integrada da sua organização financeira, com alertas e próximos passos.',button('＋ Definir limite','set-budget','secondary'))+
 '<section class="panel intelligence-health"><div class="panel-head"><div><p class="eyebrow">SAÚDE FINANCEIRA</p><h2>'+healthLabel+'</h2><p>Pontuação indicativa baseada nos dados cadastrados, não uma avaliação de crédito.</p></div><div class="health-score"><strong>'+health+'</strong><small>/100</small></div></div><div class="health-track"><i style="width:'+health+'%"></i></div><div class="metrics">'+metric('Entradas em dinheiro',money(income),'Salários, extras e reembolsos')+metric('Despesas de caixa',money(out),'Despesas que consomem dinheiro')+metric('Saldo projetado',money(net),'No período selecionado',net<0?'red':'green')+metric('Dívidas em aberto',money(debt),'Saldo devedor cadastrado',debt>0?'red':'green')+'</div></section>'+
 '<section class="grid2"><article class="panel"><div class="panel-head"><div><p class="eyebrow">RESERVA DE EMERGÊNCIA</p><h2>Seu colchão financeiro</h2><p>Meta estimada com despesas essenciais × '+reserveMonths+' meses.</p></div></div><div class="reserve-values"><strong>'+money(reserveBalance)+'</strong><span>de '+money(reserveTarget)+'</span></div><div class="health-track"><i style="width:'+reservePct+'%"></i></div><p class="micro">'+(reserveTarget?reservePct.toFixed(0)+'% da meta. Faltam '+money(Math.max(0,reserveTarget-reserveBalance))+'.':'Cadastre despesas para estimar o valor recomendado.')+'</p><button class="button secondary" data-action="set-emergency-reserve">Configurar reserva</button></article><article class="panel"><div class="panel-head"><div><p class="eyebrow">COMPARATIVO MENSAL</p><h2>Como você evoluiu?</h2><p>Comparação do saldo projetado com o mês anterior.</p></div></div>'+(previous?'<div class="comparison-value '+(delta>=0?'positive':'negative')+'">'+(delta>=0?'+':'−')+money(Math.abs(delta))+'</div><p class="micro">'+(delta>=0?'Melhora':'Redução')+' em relação a '+full(keys[idx-1])+'.</p>':'<p class="empty">Cadastre pelo menos dois meses para comparar sua evolução.</p>')+'</article></section>'+
 '<section class="panel"><div class="panel-head"><div><p class="eyebrow">ALERTAS E OPORTUNIDADES</p><h2>Pontos que merecem atenção</h2></div><span class="pill">'+alerts.length+' análise(s)</span></div><div class="insight-alert-list">'+alerts.map(a=>'<article class="insight-alert '+a.level+'"><span class="insight-alert-mark">'+(a.level==='high'?'!':a.level==='mid'?'◷':'✓')+'</span><div><b>'+esc(a.title)+'</b><p>'+esc(a.desc)+'</p></div></article>').join('')+'</div></section>'+
 '<section class="grid2"><article class="panel"><div class="panel-head"><div><p class="eyebrow">OPORTUNIDADES</p><h2>Pequenas economias</h2><p>Simulação hipotética de redução de 10% nas maiores categorias do mês.</p></div></div>'+(opportunities.length?opportunities.map(x=>'<div class="opportunity-row"><span>'+esc(x.cat)+'</span><b>'+money(x.value)+'/mês</b></div>').join(''):'<p class="empty">Registre despesas para encontrar oportunidades de economia.</p>')+'</article><article class="panel"><div class="panel-head"><div><p class="eyebrow">CONQUISTAS</p><h2>Seu progresso</h2></div></div>'+achievements.map(x=>'<div class="achievement-row"><span>✓</span>'+esc(x)+'</div>').join('')+'</article></section>'+
 '<section class="panel"><div class="panel-head"><div><h2>Maiores categorias de gastos</h2><p>Despesas do mês em análise.</p></div></div>'+(top.length?'<div class="annual-category-list">'+top.map(([cat,v])=>'<div class="annual-category-row"><div class="annual-category-label"><span>'+esc(cat)+'</span><b>'+money(v)+'</b></div><div class="annual-category-track"><i style="width:'+(privacyVisible?v/Math.max(1,top[0][1])*100:8)+'%"></i></div></div>').join('')+'</div>':'<p class="empty">Cadastre despesas para gerar análises por categoria.</p>')+'</section>'+
 '<section class="panel"><div class="panel-head"><div><h2>Limites por categoria</h2><p>Defina tetos mensais e acompanhe o orçamento.</p></div></div>'+(Object.keys(budgets).length?Object.entries(budgets).map(([cat,limit])=>{let v=monthSpent[cat]||0,p=limit?v/limit*100:0;return '<div class="budget-row"><div><b>'+esc(cat)+'</b><span>'+money(v)+' de '+money(limit)+'</span></div><div class="annual-category-track"><i style="width:'+(privacyVisible?Math.min(100,p):8)+'%" class="'+(p>=100?'over':'')+'"></i></div><button class="button text" data-action="remove-budget" data-category="'+esc(cat)+'">Remover</button></div>'}).join(''):'<p class="empty">Nenhum limite definido. Use “Definir limite” para começar.</p>')+'</section>'+
 '<p class="micro">A pontuação e as recomendações são estimativas baseadas nos lançamentos disponíveis. A redução sugerida é apenas um cenário, não uma promessa de economia.</p>';
}

function simulatorView(){
 let current=S.keys.includes(today)?today:S.keys[S.keys.length-1],m=current?M(current):null,c=current?calc(current):null,debtList=S.debts.filter(d=>(+d.valor||0)>0);
 let chosen=debtList.find(d=>d.id===decisionSim.debtId)||debtList[0]||null;
 let priority=decisionSim.priorityDebtId?debtList.find(d=>d.id===decisionSim.priorityDebtId&&d.id!==chosen?.id)||null:null;
 let monthRows=chosen&&current&&S.months[current]?[...(S.months[current].fixos||[]),...(S.months[current].parcelas||[])].filter(r=>r.debtId===chosen.id):[];
 if(!monthRows.length&&chosen){for(const k of [...S.keys].sort()){const mm=S.months[k];const found=[...(mm?.fixos||[]),...(mm?.parcelas||[])].filter(r=>r.debtId===chosen.id);if(found.length){monthRows=found;break}}}
 let scheduled=monthRows.reduce((n,r)=>n+(+r.valor||0),0);
 let defer=scheduled||(+chosen?.valorParcela||0)||(+chosen?.valor||0);
 let rate=Math.max(0,+decisionSim.interest||0),nextImpact=defer*(1+rate/100);
 let extra=Math.min(priority?Math.max(0,+priority.valor||0):0,Math.max(0,+decisionSim.extraPayment||0));
 let priorityAfter=Math.max(0,(+priority?.valor||0)-extra);
 let advanceDebt=debtList.find(d=>d.id===decisionSim.advanceDebtId)||chosen||debtList[0]||null;
 let advanceAmount=Math.min(Math.max(0,+advanceDebt?.valor||0),Math.max(0,+decisionSim.advanceAmount||0));
 let advanceRate=Math.max(0,+decisionSim.advanceRate||0),advanceMonths=Math.max(0,+decisionSim.advanceMonths||0);
 let interestSaved=advanceAmount*(advanceRate/100)*advanceMonths;
 let advanceBalance=Math.max(0,(+advanceDebt?.valor||0)-advanceAmount);
 let monthly=+decisionSim.monthlySaving||0,months=Math.max(1,+decisionSim.months||1),target=Math.max(0,+decisionSim.amount||0),saved=monthly*months;
 let purchase=Math.max(0,+decisionSim.purchaseAmount||0),parts=Math.max(1,+decisionSim.purchaseParts||1),installment=purchase/parts,roomCash=(c?.saldo||0)-purchase,roomCard=(c?.saldo||0)-installment;
 let principal=Math.max(0,(+decisionSim.financePrincipal||0)-(+decisionSim.financeDownPayment||0)),fr=Math.max(0,+decisionSim.financeRate||0)/100,fm=Math.max(1,+decisionSim.financeMonths||1),payment=fr?principal*fr/(1-Math.pow(1+fr,-fm)):principal/fm,totalFin=payment*fm;
 let extraCost=Math.max(0,+decisionSim.incomeExtraCost||0),incomeCurrent=Math.max(0,+decisionSim.incomeCurrent||0),incomeNew=Math.max(0,+decisionSim.incomeNew||0),incomeDelta=incomeNew-incomeCurrent-extraCost;
 let debtOptions=debtList.map(d=>'<option value="'+esc(d.id)+'" '+(chosen?.id===d.id?'selected':'')+'>'+esc(d.nome)+' · '+money(d.valor)+'</option>').join('');
 let advanceOptions=debtList.map(d=>'<option value="'+esc(d.id)+'" '+(advanceDebt?.id===d.id?'selected':'')+'>'+esc(d.nome)+' · '+money(d.valor)+'</option>').join('');
 return head('SIMULADOR FINANCEIRO','Teste antes de decidir.','Compare cenários sem alterar seus lançamentos reais.',button('← Visão geral','go-panel'))+
 '<section class="panel simulator-panel"><div class="panel-head"><div><p class="eyebrow">PLANEJAMENTO DE OBJETIVOS</p><h2>Quanto posso acumular?</h2><p>Simule aportes mensais e veja o resultado sem considerar rendimentos.</p></div></div><div class="simulator-fields"><label>Meta desejada (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="amount" value="'+target+'"></label><label>Aporte mensal (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="monthlySaving" value="'+monthly+'"></label><label>Prazo (meses)<input type="number" min="1" max="600" data-change="sim-input" data-field="months" value="'+months+'"></label></div><div class="simulator-result-grid"><article><span>Você acumularia</span><strong>'+money(saved)+'</strong></article><article><span>Falta para a meta</span><strong>'+money(Math.max(0,target-saved))+'</strong></article><article><span>Prazo estimado</span><strong>'+(monthly?Math.ceil(target/monthly)+' meses':'—')+'</strong></article></div><p class="micro">Cálculo simples: aporte mensal × quantidade de meses. Não considera juros, inflação nem retiradas.</p></section>'+
 '<section class="panel"><div class="panel-head"><div><p class="eyebrow">SIMULADOR DE COMPRAS</p><h2>À vista ou parcelado?</h2><p>Compare o impacto imediato e o valor mensal das parcelas.</p></div></div><div class="simulator-fields"><label>Valor da compra (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="purchaseAmount" value="'+purchase+'"></label><label>Número de parcelas<input type="number" min="1" max="120" step="1" data-change="sim-input" data-field="purchaseParts" value="'+parts+'"></label></div><div class="simulator-result-grid"><article><span>À vista, saldo após compra</span><strong>'+money(roomCash)+'</strong></article><article><span>Valor de cada parcela</span><strong>'+money(installment)+'</strong></article><article><span>Saldo após 1ª parcela</span><strong>'+money(roomCard)+'</strong></article></div><p class="micro">Comparação sem juros, tarifas ou impacto no limite do cartão. Confirme o CET e as condições antes de contratar.</p></section>'+
 '<section class="panel"><div class="panel-head"><div><p class="eyebrow">SIMULADOR DE FINANCIAMENTO</p><h2>Quanto custa financiar?</h2><p>Estimativa pela tabela Price, com parcelas fixas e taxa mensal informada.</p></div></div><div class="simulator-fields"><label>Valor financiado (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="financePrincipal" value="'+(+decisionSim.financePrincipal||0)+'"></label><label>Entrada (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="financeDownPayment" value="'+(+decisionSim.financeDownPayment||0)+'"></label><label>Juros ao mês (%)<input type="number" min="0" max="100" step=".01" data-change="sim-input" data-field="financeRate" value="'+(+decisionSim.financeRate||0)+'"></label><label>Prazo (meses)<input type="number" min="1" max="600" step="1" data-change="sim-input" data-field="financeMonths" value="'+fm+'"></label></div><div class="simulator-result-grid"><article><span>Parcela estimada</span><strong>'+money(payment)+'</strong></article><article><span>Total das parcelas</span><strong>'+money(totalFin)+'</strong></article><article><span>Juros estimados</span><strong>'+money(Math.max(0,totalFin-principal))+'</strong></article></div><p class="micro">Simulação matemática simplificada. Não inclui IOF, seguros, tarifas ou outros custos. O CET do contrato é a referência correta.</p></section>'+
 '<section class="panel"><div class="panel-head"><div><p class="eyebrow">MUDANÇA DE RENDA</p><h2>Vale a pena aceitar uma nova proposta?</h2><p>Compare a renda atual, a nova renda e os custos adicionais.</p></div></div><div class="simulator-fields"><label>Renda líquida atual (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="incomeCurrent" value="'+incomeCurrent+'"></label><label>Nova renda líquida (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="incomeNew" value="'+incomeNew+'"></label><label>Custos adicionais mensais (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="incomeExtraCost" value="'+extraCost+'"></label></div><div class="simulator-result-grid"><article><span>Variação líquida mensal</span><strong>'+money(incomeDelta)+'</strong></article><article><span>Variação anual estimada</span><strong>'+money(incomeDelta*12)+'</strong></article></div><p class="micro">Inclua transporte, alimentação, plano de saúde, perda de benefícios e outros custos.</p></section>'+
 '<section class="panel debt-simulator"><div class="panel-head"><div><p class="eyebrow">01 · ADIAR E PRIORIZAR</p><h2>Se eu adiar uma dívida, o que acontece?</h2><p>Veja o caixa liberado, o custo estimado do adiamento e o efeito de direcionar dinheiro a outra dívida.</p></div></div>'+
 (debtList.length?'<div class="simulator-fields"><label>Dívida que pretende adiar<select data-change="sim-debt">'+debtOptions+'</select></label><label>Dívida que deseja priorizar<select data-change="sim-priority"><option value="">Selecione outra dívida</option>'+debtList.filter(d=>d.id!==chosen?.id).map(d=>'<option value="'+esc(d.id)+'" '+(priority?.id===d.id?'selected':'')+'>'+esc(d.nome)+' · '+money(d.valor)+'</option>').join('')+'</select></label><label>Valor extra para pagar a dívida prioritária (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="extraPayment" value="'+extra+'"></label><label>Juros/encargos estimados do adiamento (% ao mês)<input type="number" min="0" max="100" step=".01" data-change="sim-input" data-field="interest" value="'+rate+'"></label></div><div class="simulator-result-grid"><article><span>Parcela/compromisso adiado</span><strong>'+money(defer)+'</strong><small>'+(scheduled?'Encontrado nos lançamentos do mês':'Estimado pelo cadastro da dívida; confirme o vencimento')+'</small></article><article><span>Caixa liberado agora</span><strong>'+money(defer)+'</strong><small>Antes dos encargos</small></article><article><span>Valor estimado no próximo mês</span><strong>'+money(nextImpact)+'</strong><small>Uma incidência mensal estimada</small></article></div><div class="simulator-result-grid"><article><span>Pagamento extra na prioritária</span><strong>'+money(extra)+'</strong></article><article><span>Saldo da prioritária após pagamento</span><strong>'+money(priorityAfter)+'</strong></article><article><span>Saldo devedor da dívida adiada</span><strong>'+money(chosen?.valor||0)+'</strong></article></div><div class="simulator-warning"><b>Atenção antes de adiar</b><p>É uma estimativa simples, não uma previsão do credor. Multas, juros compostos, perda de descontos, negativação e consequências legais dependem do contrato e da instituição. Confirme as condições antes de deixar de pagar.</p></div><div class="simulator-summary"><b>Leitura do cenário</b><p>'+(chosen?'Adiar “'+esc(chosen.nome)+'” libera, em tese, '+money(defer)+' neste mês. Com a taxa informada, o compromisso estimado passa a '+money(nextImpact)+' no próximo mês.':'Cadastre uma dívida para simular.')+'</p><p>'+(priority?'Se direcionar '+money(extra)+' para “'+esc(priority.nome)+'”, o saldo cadastrado cairia de '+money(priority.valor)+' para '+money(priorityAfter)+'.':'Selecione outra dívida para calcular o efeito da priorização.')+'</p><p>Nenhum lançamento, vencimento ou saldo real é alterado.</p></div>':'<p class="empty">Cadastre ao menos uma dívida para habilitar esta simulação.</p>')+'</section>'+
 '<section class="panel debt-simulator"><div class="panel-head"><div><p class="eyebrow">02 · ANTECIPAR PARCELAS</p><h2>Quanto posso economizar pagando antes?</h2><p>Estime a redução do saldo e o possível desconto de juros ao antecipar um pagamento.</p></div></div>'+
 (debtList.length?'<div class="simulator-fields"><label>Dívida que deseja antecipar<select data-change="sim-advance-debt">'+advanceOptions+'</select></label><label>Valor que pretende antecipar (R$)<input type="number" min="0" step=".01" data-change="sim-input" data-field="advanceAmount" value="'+(+decisionSim.advanceAmount||0)+'"></label><label>Taxa estimada de juros ao mês (%)<input type="number" min="0" max="100" step=".01" data-change="sim-input" data-field="advanceRate" value="'+(+decisionSim.advanceRate||0)+'"></label><label>Quantos meses antes do vencimento?<input type="number" min="0" max="600" step="1" data-change="sim-input" data-field="advanceMonths" value="'+(+decisionSim.advanceMonths||0)+'"></label></div><div class="simulator-result-grid"><article><span>Valor antecipado</span><strong>'+money(advanceAmount)+'</strong></article><article><span>Saldo devedor estimado depois</span><strong>'+money(advanceBalance)+'</strong></article><article><span>Possível economia de juros</span><strong>'+money(interestSaved)+'</strong></article></div><div class="simulator-summary"><b>Resultado estimado</b><p>'+(advanceDebt?'Ao antecipar '+money(advanceAmount)+' de “'+esc(advanceDebt.nome)+'”, o saldo cadastrado cairia de '+money(advanceDebt.valor)+' para '+money(advanceBalance)+'. Pela taxa simples informada, a economia potencial seria de '+money(interestSaved)+'.':'Selecione uma dívida.')+'</p><p>O desconto efetivo depende do contrato, do sistema de amortização e do cálculo do credor. Empréstimos e financiamentos podem usar regras diferentes; solicite o valor de quitação/antecipação atualizado.</p></div>':'<p class="empty">Cadastre uma dívida para simular a antecipação.</p>')+'</section>'+
 '<section class="panel"><h2>Saldo de referência</h2><p>Saldo projetado de '+esc(current?full(current):'nenhum mês')+': <b>'+money(c?.saldo||0)+'</b></p><p class="micro">Todos os resultados são cenários hipotéticos. A simulação não altera seus dados financeiros nem substitui o demonstrativo do credor.</p></section>'+financialEcoMode();
}
function netWorthView(){
 let assets=Array.isArray(S.preferences?.manualAssets)?S.preferences.manualAssets:[],latest=[...S.keys].sort().reverse()[0],c=latest?calc(latest):null,invested=c?c.inv:0,cash=assets.reduce((n,a)=>n+(+a.valor||0),0),liabilities=S.debts.reduce((n,d)=>n+(+d.valor||0),0),net=cash-liabilities;
 return head('PATRIMÔNIO','Veja o conjunto, não só o saldo.','Acompanhe seus ativos e compromissos em uma visão consolidada.',button('＋ Cadastrar ativo','add-asset','secondary'))+
 '<section class="panel"><div class="metrics">'+metric('Patrimônio líquido',money(net),'Ativos manuais menos dívidas',net<0?'red':'green')+metric('Ativos cadastrados',money(cash),'Bens e valores informados')+metric('Dívidas em aberto',money(liabilities),'Saldo devedor atual')+metric('Reservas e aportes do mês',money(invested),'Fluxo destinado no último mês')+'</div></section>'+
 '<section class="panel"><div class="panel-head"><div><h2>Seus ativos</h2><p>Cadastre bens e valores sem duplicar outras categorias.</p></div></div>'+(assets.length?assets.map(a=>'<div class="asset-row"><div><b>'+esc(a.nome)+'</b><small>'+esc(a.tipo||'Outro')+'</small></div><strong>'+money(a.valor)+'</strong><button class="button text" data-action="remove-asset" data-id="'+esc(a.id)+'">Remover</button></div>').join(''):'<p class="empty">Nenhum ativo manual cadastrado.</p>')+'</section>'+
 '<section class="panel"><h2>Como este patrimônio é calculado</h2><p>Ativos cadastrados manualmente − saldos devedores das dívidas.</p><p class="micro">Reservas e aportes mensais são fluxos, não saldos acumulados, por isso aparecem separadamente e não são somados automaticamente. Cadastre bens e saldos bancários manualmente, sem duplicar valores.</p></section>';
}

