function setEmergencyReserve(){
 S.preferences=S.preferences||{};
 openForm('Reserva de emergência',[{type:'section',label:'CONFIGURAÇÃO DA RESERVA'},{name:'emergencyReserveBalance',label:'Quanto já possui guardado (R$)',type:'number',min:0,step:'.01'},{name:'emergencyReserveMonths',label:'Quantos meses de despesas deseja cobrir?',type:'number',min:1,max:24,step:1}],{emergencyReserveBalance:+S.preferences.emergencyReserveBalance||0,emergencyReserveMonths:+S.preferences.emergencyReserveMonths||6},v=>{
 S.preferences.emergencyReserveBalance=Math.max(0,+v.emergencyReserveBalance||0);S.preferences.emergencyReserveMonths=Math.min(24,Math.max(1,+v.emergencyReserveMonths||6));save();
 });
}
function setCategoryBudget(){S.preferences=S.preferences||{};S.preferences.categoryBudgets=S.preferences.categoryBudgets||{};openForm('Definir limite por categoria',[{type:'section',label:'ORÇAMENTO MENSAL'},{name:'categoria',label:'Categoria',type:'select',required:true,options:S.cats.map(x=>({value:x,label:x}))},{name:'valor',label:'Limite mensal (R$)',type:'number',min:.01,step:'.01',required:true}],{categoria:S.cats[0]||'',valor:''},v=>{let val=+v.valor;if(!(val>0)){appToast('Informe um limite maior que zero.','error');return false}S.preferences.categoryBudgets[v.categoria]=val;save();return true})}function addManualAsset(){openForm('Adicionar patrimônio',[{type:'section',label:'IDENTIFICAÇÃO DO BEM'},{name:'nome',label:'Nome do ativo',type:'text',required:true},{name:'valor',label:'Valor estimado atual (R$)',type:'number',min:0,step:'.01',required:true},{name:'tipo',label:'Classificação',type:'select',options:['Bem','Dinheiro','Investimento','Outro']}],{nome:'',valor:'',tipo:'Bem'},v=>{S.preferences=S.preferences||{};S.preferences.manualAssets=Array.isArray(S.preferences.manualAssets)?S.preferences.manualAssets:[];S.preferences.manualAssets.push({id:'asset-'+Date.now(),nome:v.nome,valor:+v.valor||0,tipo:v.tipo});save();return true})}function parseCsvLine(line,delimiter){let out=[],value='',quoted=false;for(let i=0;i<line.length;i++){let ch=line[i];if(ch==='"'){if(quoted&&line[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(ch===delimiter&&!quoted){out.push(value.trim());value=''}else value+=ch}out.push(value.trim());return out}
function parseStatementAmount(raw){let v=String(raw||'0').trim().replace(/[^0-9,.-]/g,'');if(v.includes(',')&&v.includes('.'))v=v.lastIndexOf(',')>v.lastIndexOf('.')?v.split('.').join('').replace(',','.'):v.split(',').join('');else if(v.includes(','))v=v.replace(',','.');return Number(v)}
function importStatementFile(file){
 if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let raw=String(reader.result||''),rows=[];
 if(/\.ofx$/i.test(file.name)||/<OFX>/i.test(raw)){let blocks=raw.split(/<STMTTRN>/i).slice(1);rows=blocks.map(b=>({date:(b.match(/<DTPOSTED>(\d{8})/)||[])[1],name:(b.match(/<NAME>([^<\r\n]+)/i)||b.match(/<MEMO>([^<\r\n]+)/i)||[])[1]||'Movimentação OFX',amount:+((b.match(/<TRNAMT>([-\d.]+)/i)||[])[1]||0)}))}
 else{let lines=raw.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean),delimiter=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';let matrix=lines.map(line=>parseCsvLine(line,delimiter)),header=matrix.shift().map(x=>x.toLowerCase()),find=names=>header.findIndex(h=>names.some(n=>h.includes(n))),di=find(['data','date','dt']),ni=find(['descri','hist','memo','name','lançamento']),vi=find(['valor','amount','value']);if(vi<0)throw new Error('Não encontrei uma coluna de valor. Use cabeçalhos como Data, Descrição e Valor.');rows=matrix.map(r=>({date:di>=0?r[di]:'',name:ni>=0?r[ni]:'Movimentação importada',amount:parseStatementAmount(r[vi])}))}
 rows=rows.filter(r=>Number.isFinite(r.amount)&&r.amount!==0);if(!rows.length)throw new Error('Nenhuma movimentação válida foi encontrada.');window.__statementPending=rows;let box=$('#statement-preview');if(!box)return;box.innerHTML='<p><b>'+rows.length+' movimentação(ões) identificadas.</b> Confira antes de importar.</p><div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Tipo</th><th>Valor</th></tr></thead><tbody>'+rows.slice(0,30).map(r=>'<tr><td>'+esc(r.date)+'</td><td>'+esc(r.name)+'</td><td>'+(r.amount<0?'Saída':'Entrada')+'</td><td>'+money(Math.abs(r.amount))+'</td></tr>').join('')+'</tbody></table></div><p class="micro">Exibindo até 30 linhas. Confirme somente se o extrato e os valores estiverem corretos.</p>'+button('Confirmar importação','confirm-statement','primary')+button('Cancelar','cancel-statement','text');
 }catch(e){alert(e.message||'Não foi possível interpretar o extrato.')}};reader.readAsText(file)}
function confirmStatementImport(){
 let rows=window.__statementPending||[];if(!rows.length)return;let fallback=S.keys.includes(today)?today:S.keys[S.keys.length-1];if(!fallback){let d=new Date();fallback=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
 let added=0,duplicates=0,months=new Set();
 rows.forEach(r=>{let date=String(r.date||''),day=1,k=fallback;if(date.length===8&&date.split('').every(ch=>ch>='0'&&ch<='9')){day=+date.slice(6,8);k=date.slice(0,4)+'-'+date.slice(4,6)}else if(date.length===10&&date[4]==='-'){day=+date.slice(8,10);k=date.slice(0,7)}else if(date.length===10&&date[2]==='/'){day=+date.slice(0,2);k=date.slice(6,10)+'-'+date.slice(3,5)}let parts=k.split('-');if(parts.length!==2||parts[1]<'01'||parts[1]>'12')k=fallback;if(!S.months[k])M(k);if(!S.keys.includes(k))S.keys.push(k);months.add(k);let m=M(k),name=String(r.name||'Movimentação importada').slice(0,100),value=Math.abs(+r.amount||0),exists=[...m.gastos,...m.fixos,...m.parcelas].some(x=>x.nome===name&&Math.abs((+x.valor||0)-value)<.005&&(+x.dia||1)===day);if(exists){duplicates++;return}if(r.amount<0)m.gastos.push({nome:name,dia:Math.max(1,Math.min(31,day)),tipo:'Débito',cat:S.cats.includes('Outros')?'Outros':S.cats[0],bancoId:'',valor:value});else{let mid='mv-import-'+Date.now()+'-'+added,bid='import-'+Date.now()+'-'+added;m.bonusItems=Array.isArray(m.bonusItems)?m.bonusItems:[];m.bonusItems.push({id:bid,descricao:name,valor:value,data:k+'-'+String(day).padStart(2,'0'),includeInBalance:true,movementId:mid});S.movements.push({id:mid,nome:name,valor:value,data:k+'-'+String(day).padStart(2,'0'),bancoId:'',tipo:'Entrada importada',includeInBalance:true,bonusItemId:bid})}added++});
 S.keys=[...new Set(S.keys)].sort();window.__statementPending=[];save();render();alert(added+' movimentação(ões) importadas em '+months.size+' mês(es). '+duplicates+' possível(is) duplicidade(s) ignorada(s).');
}

